using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using LighFight.Runtime;
public static class TripoWitchSupportSetup{
public static void Run(){const string folder="Assets/LighFight/Art/Drafts/TripoWitchPlayable";var model=AssetDatabase.LoadAssetAtPath<GameObject>(folder+"/Source/WitchFull/model.fbx");var skin=model.GetComponentInChildren<SkinnedMeshRenderer>();var mesh=skin.sharedMesh;var vertices=mesh.vertices;var support=new List<int>();var geometry=new List<int>();float ankle=skin.bones.Where(b=>NativeRigBones.CanonicalName(b.name).Contains("Foot")).Max(b=>b.position.y);using(var counts=mesh.GetBonesPerVertex())using(var weights=mesh.GetAllBoneWeights()){int offset=0;for(int i=0;i<vertices.Length;i++){bool foot=false;for(int k=0;k<counts[i];k++){var w=weights[offset+k];var name=NativeRigBones.CanonicalName(skin.bones[w.boneIndex].name);if(w.weight>0&&(name.Contains("Foot")||name.Contains("Toe")))foot=true;}offset+=counts[i];bool low=skin.transform.TransformPoint(vertices[i]).y<=ankle+.05f;if(low)geometry.Add(i);if(foot||low)support.Add(i);}}File.WriteAllLines(folder+"/sole-support-full-original-vertex-indices.txt",support.Select(i=>i.ToString()));File.WriteAllLines(folder+"/full-shoe-holdout.txt",geometry.Select(i=>i.ToString()));Directory.CreateDirectory("WitchEvidence");File.WriteAllText("WitchEvidence/support-definition.txt","Original foot/toe any positive influence OR rest y <= highest ankle+.05m; geometry reference independently selected from lower rest band. count="+support.Count+" geometry="+geometry.Count+" vertices="+vertices.Length+" ankle="+ankle);AssetDatabase.Refresh();TripoWitchFullNativeSetup.Run();}
}
